306	/// 对象标识符（OID），以各段弧的数值保存，用于向调用方展示实际标识。
307	#[derive(Debug, Clone, PartialEq, Eq, Hash)]
308	pub struct ObjectIdentifier(Vec<u64>);
309	
310	impl ObjectIdentifier {
311	    /// 返回各段弧的数值，例如 Ed25519 为 `[1, 3, 101, 112]`。
312	    pub fn arcs(&self) -> &[u64] {
313	        &self.0
314	    }
315	}
316	
317	impl fmt::Display for ObjectIdentifier {
318	    /// 点分十进制写法，例如 `1.3.101.112`。
319	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
320	        let mut arcs = self.0.iter();
321	        if let Some(first) = arcs.next() {
322	            write!(f, "{first}")?;
323	            for arc in arcs {
324	                write!(f, ".{arc}")?;
325	            }
326	        }
327	        Ok(())
328	    }
329	}
330	
331	/// 导入 Ed25519 公钥失败时返回的类型化错误。
332	///
333	/// 调用方按变体即可区分两类失败，无需分析提示字符串：编码或公钥结构
334	/// 不合法是 [`Malformed`](Self::Malformed)；结构完整、DER 合法但算法
335	/// 标识不是 Ed25519 是 [`UnsupportedAlgorithm`](Self::UnsupportedAlgorithm)。
336	/// 任何失败都不会产出可继续使用的公钥对象。
337	#[derive(Debug, Clone, PartialEq, Eq)]
338	pub enum ImportPublicKeyError {
339	    /// 输入不是一份完整、规范的 DER 编码 SubjectPublicKeyInfo：截断、
340	    /// 声明长度与实际内容不符、非规范长度编码、算法参数未缺省（含写成
341	    /// NULL）、位串未使用位数非零、容器中出现多余字段或对象之后还有
342	    /// 字节等；当算法标识确为 Ed25519（`1.3.101.112`）时，公钥长度不是
343	    /// 32 字节也属于本变体。注意：其他算法容器里的公钥长度（例如
344	    /// Ed448 的 57 字节）不作为格式问题——那属于
345	    /// [`UnsupportedAlgorithm`](Self::UnsupportedAlgorithm)。
346	    Malformed,
347	    /// 整体编码合法，但算法标识不是 Ed25519（`1.3.101.112`）；携带实际
348	    /// 标识供调用方展示，例如一份完整的 Ed448（`1.3.101.113`）公钥。
349	    UnsupportedAlgorithm(ObjectIdentifier),
350	}
351	
352	impl fmt::Display for ImportPublicKeyError {
353	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
354	        match self {
355	            ImportPublicKeyError::Malformed => write!(
356	                f,
357	                "input is not a well-formed DER-encoded Ed25519 SubjectPublicKeyInfo"
358	            ),
359	            ImportPublicKeyError::UnsupportedAlgorithm(oid) => write!(
360	                f,
361	                "unsupported public key algorithm {oid} (expected Ed25519, 1.3.101.112)"
362	            ),
363	        }
364	    }
365	}
366	
367	impl Error for ImportPublicKeyError {}
368	
369	const TAG_SEQUENCE: u8 = 0x30;
370	const TAG_OID: u8 = 0x06;
371	const TAG_BIT_STRING: u8 = 0x03;
372	
373	/// 读取一个 DER TLV，返回（标签，内容，剩余字节）。
374	///
375	/// 只接受规范（最短）定长编码：拒绝不定长形式、长形式的前导零字节，
376	/// 以及本可以用短形式表示的长度；声明长度超出实际剩余内容同样失败。
377	/// 本模块只使用单字节通用标签，多字节标签形式一律拒绝。
378	fn read_der_tlv(data: &[u8]) -> Option<(u8, &[u8], &[u8])> {
379	    let (&tag, rest) = data.split_first()?;
380	    if tag & 0x1f == 0x1f {
381	        return None;
382	    }
383	    let (&first_len, rest) = rest.split_first()?;
384	    let (len, rest) = if first_len & 0x80 == 0 {
385	        (first_len as usize, rest)
386	    } else {
387	        let n = (first_len & 0x7f) as usize;
388	        // 0x80 是不定长形式，DER 不允许；长度本身也不允许超过 8 字节。
389	        if n == 0 || n > 8 || rest.len() < n {
390	            return None;
391	        }
392	        let (len_bytes, rest) = rest.split_at(n);
393	        // 前导零字节是非规范编码。
394	        if len_bytes[0] == 0 {
395	            return None;
396	        }
397	        let mut value: u64 = 0;
398	        for &b in len_bytes {
399	            value = (value << 8) | u64::from(b);
400	        }
401	        // 能用短形式表示的长度却用了长形式，同样是非规范编码。
402	        if value < 128 {
403	            return None;
404	        }
405	        (usize::try_from(value).ok()?, rest)
406	    };
407	    if rest.len() < len {
408	        return None;
409	    }
410	    let (content, rest) = rest.split_at(len);
411	    Some((tag, content, rest))
412	}
413	
414	/// 把 OID 的 DER 内容字节解码为各段弧的数值。
415	///
416	/// 只接受规范编码：内容非空，每个子标识符按最短形式编码（不允许
417	/// 前导的 0x80 字节），最后一个子标识符必须完整结束。各段弧以 u64
418	/// 保存，因此每段数值都必须落在 u64 范围内；第一个子标识符合并编码
419	/// 前两段弧（首段为 2 时合并值为 80 + 第二段），最大可到
420	/// `u64::MAX + 80`，超出该上界的合并值或超出 u64 的后续各段都属于
421	/// 编码损坏，不得截断、回绕或改写成别的数值。
422	fn decode_oid(content: &[u8]) -> Option<ObjectIdentifier> {
423	    // 合法子标识符的最大值：首段为 2、第二段为 u64::MAX 时，合并编码的
424	    // 第一个子标识符为 u64::MAX + 80。子标识符的数值在编码过程中只会
425	    // 增大，一旦超过该上界就不可能再对应任何可表示的弧，可立即判定
426	    // 编码损坏；累加器因此始终远小于 u128::MAX，移位不会溢出。
427	    const MAX_SUBIDENTIFIER: u128 = u64::MAX as u128 + 80;
428	
429	    if content.is_empty() {
430	        return None;
431	    }
432	    let mut subidentifiers: Vec<u128> = Vec::new();
433	    let mut value: u128 = 0;
434	    let mut in_arc = false;
435	    for &b in content {
436	        if !in_arc {
437	            // 子标识符首字节为 0x80 是前导零的非规范编码。
438	            if b == 0x80 {
439	                return None;
440	            }
441	            in_arc = true;
442	        }
443	        value = (value << 7) | u128::from(b & 0x7f);
444	        if value > MAX_SUBIDENTIFIER {
445	            return None;
446	        }
447	        if b & 0x80 == 0 {
448	            subidentifiers.push(value);
449	            value = 0;
450	            in_arc = false;
451	        }
452	    }
453	    // 最后一个子标识符的续位未结束：内容被截断。
454	    if in_arc {
455	        return None;
456	    }
457	    let (&first, rest) = subidentifiers.split_first()?;
458	    // 第一个子标识符合并编码前两段弧：0..=39 → 0.x，40..=79 → 1.x，
459	    // 其余 → 2.x。首段为 2 时第二段可以接近 u64::MAX，合并值因此
460	    // 可能超过 u64，必须先按 u128 拆开再逐段检查范围。
461	    let (arc0, arc1) = if first < 40 {
462	        (0, first)
463	    } else if first < 80 {
464	        (1, first - 40)
465	    } else {
466	        (2, first - 80)
467	    };
468	    let mut arcs = Vec::with_capacity(rest.len() + 2);
469	    arcs.push(u64::try_from(arc0).ok()?);
470	    arcs.push(u64::try_from(arc1).ok()?);
471	    for &arc in rest {
472	        // 后续每段都必须落在 u64 范围内，超出即编码损坏。
473	        arcs.push(u64::try_from(arc).ok()?);
474	    }
475	    Some(ObjectIdentifier(arcs))
476	}
