541	    impl Read for ChunkedReader<'_> {
542	        fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
543	            if self.pos == self.data.len() {
544	                return Ok(0);
545	            }
546	            let mut limit = buf.len();
547	            if !self.chunk_sizes.is_empty() {
548	                limit = limit.min(self.chunk_sizes[self.chunk_index % self.chunk_sizes.len()]);
549	                self.chunk_index += 1;
550	            }
551	            let n = limit.min(self.data.len() - self.pos);
552	            buf[..n].copy_from_slice(&self.data[self.pos..self.pos + n]);
553	            self.pos += n;
554	            Ok(n)
555	        }
556	    }
