1028	        assert_eq!(key.as_bytes(), &RFC8410_SPKI[12..]);
1029	        // 文本表示是公钥本身的 64 个小写十六进制字符，不是公钥的 SHA-256 摘要。
1030	        assert_eq!(key.to_hex(), RFC8410_KEY_HEX);
