1088	        // 外层 SEQUENCE 内容 67(0x43) = 算法序列 7 + 位串 60，
1089	        // 位串内容 58(0x3a) = 1 字节未使用位数 + 57 字节公钥，
1090	        // 全程短形式长度编码，无多余字段、无尾随字节。
1091	        let mut expected = vec![
1092	            0x30, 0x43, 0x30, 0x05, 0x06, 0x03, 0x2b, 0x65, 0x71, 0x03, 0x3a, 0x00,
1093	        ];
