    #[test]
    fn multi_byte_oid_arc_reports_unsupported_with_original_arcs() {
        // 1.3.101.200：最后一段 200 需要用两个字节（0x81 0x48）编码。
        // 结构完整、DER 规范，只是算法不是 Ed25519。
        let der = spki_der(&[0x2b, 0x65, 0x81, 0x48], &[0x42; 32]);
