                assert_eq!(oid.arcs(), &[1, 3, 101, 112, 255, 300]);
                assert_eq!(oid.to_string(), "1.3.101.112.255.300");
            }
            other => panic!("expected UnsupportedAlgorithm, got {other:?}"),
        }
    }

