430	/// 用法错误的完整约定：退出码 2、标准输出为空、标准错误说明问题并给出用法。
431	fn assert_usage_error(output: &Output) -> String {
432	    assert_eq!(output.status.code(), Some(2), "exit code: {output:?}");
433	    assert!(
434	        output.stdout.is_empty(),
435	        "stdout must be empty on usage error: {:?}",
436	        String::from_utf8_lossy(&output.stdout)
437	    );
438	    let stderr = String::from_utf8_lossy(&output.stderr);
439	    assert!(stderr.contains("Usage:"), "usage must be shown: {stderr:?}");
440	    stderr.into_owned()
441	}
