987	// ── 标准输出写入失败 ─────────────────────────────────────────────────────────
988	
989	#[cfg(unix)]
990	mod output_failures {
991	    use super::*;
992	    use std::fs::OpenOptions;
993	    use std::os::unix::io::{FromRawFd, RawFd};
994	    use std::process::Stdio;
995	
996	    unsafe extern "C" {
997	        fn pipe(pipefd: *mut RawFd) -> std::os::raw::c_int;
998	    }
999	
1000	    /// 构造一个读端已经关闭的管道写端：子进程一写标准输出就收到 EPIPE，
1001	    /// 模拟“结果交给管道而接收方已提前关闭”。
1002	    fn closed_pipe_stdout() -> Stdio {
1003	        let mut fds: [RawFd; 2] = [-1, -1];
1004	        assert_eq!(unsafe { pipe(fds.as_mut_ptr()) }, 0);
1005	        // 读端立即关闭（File 析构关闭该 fd）。
1006	        drop(unsafe { std::fs::File::from_raw_fd(fds[0]) });
1007	        Stdio::from(unsafe { std::fs::File::from_raw_fd(fds[1]) })
1008	    }
1009	
1010	    /// 以读不开写方式打开一个普通文件得到的 fd：对它写入会被内核拒绝，
1011	    /// 模拟“标准输出被重定向到拒绝写入的位置”。
1012	    fn read_only_stdout(path: &Path) -> Stdio {
1013	        let file = OpenOptions::new()
1014	            .read(true)
1015	            .write(false)
1016	            .open(path)
1017	            .expect("open read-only fd");
1018	        Stdio::from(file)
1019	    }
1020	
1021	    fn run_with_stdout(stdout: Stdio, args: &[&OsStr]) -> Output {
1022	        inkseal()
1023	            .args(args)
1024	            .stdout(stdout)
1025	            .output()
1026	            .expect("failed to run inkseal")
1027	    }
1028	
1029	    /// 输出失败的完整约定：退出码 1、标准输出为空、标准错误只有一条
1030	    /// inkseal: 的写入失败提示（保留系统原因），没有任何崩溃信息。
1031	    fn assert_output_failure(output: &Output) -> String {
1032	        assert_eq!(output.status.code(), Some(1), "exit code: {output:?}");
1033	        assert!(
1034	            output.stdout.is_empty(),
1035	            "captured stdout must be empty: {:?}",
1036	            String::from_utf8_lossy(&output.stdout)
1037	        );
1038	        let stderr = String::from_utf8(output.stderr.clone()).expect("stderr must be UTF-8");
1039	        assert!(
1040	            stderr.starts_with("inkseal: unable to write to standard output"),
1041	            "must report an output failure, not another error: {stderr:?}"
1042	        );
1043	        assert!(
1044	            stderr.ends_with('\n') && !stderr[..stderr.len() - 1].contains('\n'),
1045	            "hint must be a single line: {stderr:?}"
1046	        );
1047	        // 系统给出的具体原因必须保留，且不能是 Rust 崩溃信息。
1048	        assert!(!stderr.contains("panicked"), "must not crash: {stderr:?}");
1049	        stderr
1050	    }
1051	
