1188	// 用户把标准错误接到另一个程序，而接收方提前关闭管道时，失败提示本身可能
1189	// 写不出去。提示说明的是已经发生的失败：无论标准错误是否还可读，命令对
1190	// 本次操作的判断（退出码 1 或 2）都不能改变，更不能因 eprintln! 在
1191	// EPIPE/EBADF 上 panic 而以 101 崩溃。
1192	#[cfg(unix)]
1193	mod stderr_failures {
1194	    use super::*;
1195	    use std::fs::OpenOptions;
1196	    use std::io;
1197	    use std::os::raw::{c_int, c_void};
1198	    use std::os::unix::io::{FromRawFd, RawFd};
1199	    use std::process::Stdio;
1200	
1201	    unsafe extern "C" {
1202	        fn pipe(pipefd: *mut RawFd) -> c_int;
1203	        fn pipe2(pipefd: *mut RawFd, flags: c_int) -> c_int;
1204	        fn read(fd: RawFd, buf: *mut c_void, count: usize) -> isize;
1205	        fn close(fd: RawFd) -> c_int;
1206	        fn fcntl(fd: RawFd, cmd: c_int, arg: c_int) -> c_int;
