1209	    /// 构造一个读端已经关闭的管道写端：子进程一写标准错误就收到 EPIPE，
1210	    /// 模拟“错误提示交给管道而接收方已提前关闭”，且一个字节都送不出去。
1211	    fn closed_pipe_stderr() -> Stdio {
1212	        let mut fds: [RawFd; 2] = [-1, -1];
1213	        assert_eq!(unsafe { pipe(fds.as_mut_ptr()) }, 0);
1214	        // 读端立即关闭（File 析构关闭该 fd）。
1215	        drop(unsafe { std::fs::File::from_raw_fd(fds[0]) });
1216	        Stdio::from(unsafe { std::fs::File::from_raw_fd(fds[1]) })
1217	    }
1218	
1219	    /// 以只读方式打开一个普通文件得到的 fd：对它写入会被内核拒绝，
1220	    /// 模拟“标准错误从一开始就被定向到拒绝写入的位置”。
1221	    fn read_only_stderr(path: &Path) -> Stdio {
1222	        let file = OpenOptions::new()
1223	            .read(true)
1224	            .write(false)
1225	            .open(path)
1226	            .expect("open read-only fd");
1227	        Stdio::from(file)
1228	    }
