1494	    /// 管道只接收了提示的前几个字节、接收方便提前关闭时，子进程在后续
1495	    /// 写入上收到 EPIPE：已发出的字节保留，退出码仍为 1，进程正常结束。
1496	    ///
1497	    /// 确定性地制造“部分送达后失败”：把管道容量缩到一个页面（4096），
1498	    /// 再让提示本身远大于该容量（超长路径触发的文件错误）。内核对
1499	    /// 大于 PIPE_BUF 的阻塞写是非原子的——写满容量后子进程阻塞等待，
1500	    /// 此时关闭读端，剩余写入必然以 EPIPE 失败，而提示开头的字节已经
1501	    /// 送达。若提示仍经由 eprintln! 写出，子进程会 panic（101/信号）。
1502	    #[cfg(target_os = "linux")]
1503	    #[test]
1504	    fn partial_stderr_write_failure_keeps_exit_code_without_panic() {
1505	        const F_SETPIPE_SZ: c_int = 1024 + 7;
1506	        // arm64/x86-64 Linux 上 O_CLOEXEC 均为 02000000（八进制）。
1507	        const O_CLOEXEC: c_int = 0o2000000;
1508	
1509	        let dir = TestDir::new("stderr-partial");
1510	        // 单条错误提示远超 PIPE_BUF（4096）：含约 10000 字节的路径名。
1511	        // 该路径无法打开（ENAMETOOLONG），属于退出码 1 的文件访问失败。
1512	        let path = dir.path().join("A".repeat(10_000));
1513	
1514	        // pipe2(…, O_CLOEXEC) 至关重要：读端不能被子进程继承，否则测试
1515	        // 关闭自己的读端副本后子进程仍持有读端，会无限阻塞地写给自己。
1516	        let mut fds: [RawFd; 2] = [-1, -1];
1517	        assert_eq!(
1518	            unsafe { pipe2(fds.as_mut_ptr(), O_CLOEXEC) },
1519	            0,
1520	            "{}",
1521	            io::Error::last_os_error()
1522	        );
1523	        let set = unsafe { fcntl(fds[1], F_SETPIPE_SZ, 4096) };
1524	        assert!(set >= 0, "shrink pipe: {}", io::Error::last_os_error());
1525	
1526	        let write_end = unsafe { std::fs::File::from_raw_fd(fds[1]) };
1527	        let child = inkseal()
1528	            .args(["digest"])
1529	            .arg(path.as_os_str())
1530	            .stdout(Stdio::piped())
1531	            .stderr(Stdio::from(write_end))
1532	            .spawn()
1533	            .expect("failed to run inkseal");
1534	
1535	        // 子进程的首次写入已填满 4096 字节容量后阻塞；一次性取出这段
1536	        // 连续的提示前缀（在子进程补入更多字节之前读完）。
1537	        let mut prefix = vec![0u8; 4096];
1538	        read_full(fds[0], &mut prefix);
1539	        assert!(
1540	            prefix.starts_with(b"inkseal: cannot open '"),
1541	            "delivered prefix must be the real hint: {:?}",
1542	            String::from_utf8_lossy(&prefix[..40.min(prefix.len())])
1543	        );
1544	
1545	        // 接收方提前关闭：管道中已送达的提示前缀无需也无法补齐，
1546	        // 子进程剩余写入立即失败，但必须仍以退出码 1 正常结束。
1547	        assert_eq!(unsafe { close(fds[0]) }, 0);
1548	
1549	        let output = child.wait_with_output().expect("failed to wait");
1550	        assert_eq!(output.status.code(), Some(1), "{output:?}");
1551	        assert!(output.stdout.is_empty(), "{output:?}");
1552	        assert!(
1553	            !String::from_utf8_lossy(&output.stderr).contains("panicked"),
1554	            "must not crash: {output:?}"
1555	        );
1556	    }
1557	
1558	    /// 阻塞地从 fd 读满 `buf`，EINTR 立即重试。
1559	    #[cfg(target_os = "linux")]
1560	    fn read_full(fd: RawFd, mut buf: &mut [u8]) {
1561	        while !buf.is_empty() {
1562	            let n = unsafe { read(fd, buf.as_mut_ptr().cast::<c_void>(), buf.len()) };
1563	            assert!(n > 0, "read pipe: {}", io::Error::last_os_error());
1564	            let len = n as usize;
1565	            buf = &mut buf[len..];
1566	        }
1567	    }
1568	}
1569	
1570	// ── 读取临时受阻后继续（EINTR 与短读）与部分读取后失败 ─────────────────────────
1571	//
1572	// check-digest 打开文件后，读取循环必须持续到明确读到文件结束：一次 read
1573	// 只返回少量字节（短读）不是结束，可恢复的临时中断（EINTR，一个字节都没
1574	// 读到）也不是结束，二者都必须在原位置继续；只有 read 明确返回 0 才是
1575	// 结束。若已读入部分内容后出现真正的读取错误，这是读取失败：退出码 1、
1576	// 标准输出为空、沿用 `cannot read` 提示并给出路径与具体原因，绝不能因为
1577	// “已经读到的前缀摘要恰好等于预期摘要”而报 OK，也不能退化为不匹配。
1578	//
1579	// 与输出侧重试相同，这类读取序列无法从父进程一侧确定性地制造，因此用
1580	// LD_PRELOAD 垫片拦截子进程的 read，按 INKSEAL_READ_SHIM 给出的逗号分隔
1581	// 脚本逐步注入临时中断、短读与不可恢复错误，脚本耗尽后透传真实读取。
1582	#[cfg(target_os = "linux")]
1583	mod read_retry {
1584	    use super::*;
1585	    use std::sync::OnceLock;
1586	
1587	    /// LD_PRELOAD 垫片源码：拦截子进程对已打开输入文件（fd 3 及以上）的
1588	    /// read 调用，按 INKSEAL_READ_SHIM 的逗号分隔脚本逐步执行，脚本耗尽
1589	    /// 后透传真实读取。步骤：`i` = 返回 EINTR（不读到任何字节）；
1590	    /// `sN` = 最多读取 N 字节的短读；`eN` = 返回 errno 为 N 的真实错误。
1591	    ///
1592	    /// 垫片自身读取时直接走 read 系统调用，绕开对 read 符号的拦截，否则
1593	    /// 透传分支会递归进入自己。垫片不引入任何 crate 依赖，测试运行时用
1594	    /// rustc 编译为 cdylib。
1595	    const SHIM_SOURCE: &str = r#"
1596	use std::os::raw::{c_int, c_void};
1597	use std::sync::atomic::{AtomicUsize, Ordering};
1598	use std::sync::OnceLock;
1599	
1600	#[derive(Clone, Copy)]
1601	enum Step {
1602	    Intr,
1603	    Short(usize),
1604	    Errno(c_int),
1605	}
1606	
1607	fn steps() -> &'static [Step] {
1608	    static STEPS: OnceLock<Vec<Step>> = OnceLock::new();
1609	    STEPS
1610	        .get_or_init(|| {
1611	            std::env::var("INKSEAL_READ_SHIM")
1612	                .unwrap_or_default()
1613	                .split(',')
1614	                .filter(|token| !token.is_empty())
1615	                .map(|token| {
1616	                    if token == "i" {
1617	                        Step::Intr
1618	                    } else if let Some(n) = token.strip_prefix('s') {
1619	                        Step::Short(n.parse().expect("short-read length"))
1620	                    } else if let Some(e) = token.strip_prefix('e') {
1621	                        Step::Errno(e.parse().expect("errno"))
1622	                    } else {
1623	                        panic!("unknown shim step: {token}");
1624	                    }
1625	                })
1626	                .collect()
1627	        })
1628	        .as_slice()
1629	}
1630	
1631	static STEP_INDEX: AtomicUsize = AtomicUsize::new(0);
1632	
1633	unsafe extern "C" {
1634	    fn syscall(number: isize, ...) -> isize;
1635	    fn __errno_location() -> *mut c_int;
1636	}
1637	
1638	#[cfg(target_arch = "x86_64")]
1639	const SYS_READ: isize = 0;
1640	#[cfg(target_arch = "aarch64")]
1641	const SYS_READ: isize = 63;
1642	
1643	const EINTR: c_int = 4;
1644	
1645	fn fail(errno: c_int) -> isize {
1646	    unsafe { *__errno_location() = errno };
1647	    -1
1648	}
1649	
1650	fn real_read(fd: c_int, buf: *mut c_void, count: usize) -> isize {
1651	    // 直接发起 read 系统调用：不能调用 libc 的 read，否则会被本垫片
1652	    // 再次拦截而无限递归。
1653	    unsafe { syscall(SYS_READ, fd, buf, count) }
1654	}
1655	
1656	#[no_mangle]
1657	pub unsafe extern "C" fn read(fd: c_int, buf: *mut c_void, count: usize) -> isize {
1658	    // 只驱动被核对的输入文件：子进程的标准描述符固定为 0–2，命令打开
1659	    // 文件后得到 fd 3。脚本耗尽后一律透传，启动阶段即便存在其他读取
1660	    // （已确认本进程没有）也不会受到影响。
1661	    if fd >= 3 {
1662	        let index = STEP_INDEX.fetch_add(1, Ordering::SeqCst);
1663	        match steps().get(index) {
1664	            Some(Step::Intr) => return fail(EINTR),
1665	            Some(Step::Errno(errno)) => return fail(*errno),
1666	            Some(Step::Short(limit)) => return real_read(fd, buf, count.min(*limit)),
1667	            None => {}
1668	        }
1669	    }
1670	    real_read(fd, buf, count)
1671	}
1672	"#;
1673	
1674	    /// Linux 上各架构一致的 errno 值。
1675	    const EIO: i32 = 5;
1676	    const EACCES: i32 = 13;
1677	
1678	    /// errno 5（EIO）经标准库显示的具体原因。
1679	    const EIO_REASON: &str = "Input/output error (os error 5)";
1680	    /// errno 13（EACCES）经标准库显示的具体原因。
1681	    const EACCES_REASON: &str = "Permission denied (os error 13)";
1682	
1683	    /// 每个测试进程只编译一次垫片，产物放在临时目录。
1684	    fn read_shim() -> &'static Path {
1685	        static SHIM: OnceLock<PathBuf> = OnceLock::new();
1686	        SHIM.get_or_init(|| {
1687	            let dir = std::env::temp_dir()
1688	                .join(format!("inkseal-read-shim-{}", std::process::id()));
1689	            fs::create_dir_all(&dir).expect("create shim dir");
1690	            let source = dir.join("read_shim.rs");
1691	            let library = dir.join("libinkseal_read_shim.so");
1692	            fs::write(&source, SHIM_SOURCE).expect("write shim source");
1693	            let rustc = std::env::var_os("RUSTC").unwrap_or_else(|| "rustc".into());
1694	            let status = Command::new(rustc)
1695	                .arg("--edition=2021")
1696	                .arg("--crate-type=cdylib")
1697	                .arg("-O")
1698	                .arg("-o")
1699	                .arg(&library)
1700	                .arg(&source)

